<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Auth;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Media;final class MediaController extends AdminController{public function index(Request $w):Response{$a=Media::query()->orderBy('id','DESC')->paginate($this->pageNumber($w),40);$a['items']=Media::castAll($a['items']);return $this->view('admin/media',['res'=>$a,'meta'=>['title'=>t('admin.media')]]);}public function upload(Request $S):Response{$A=$S->files['files']??null;if(!$A){return $this->redirect('/admin/media');}$a=0;$q=is_array($A['name'])?count($A['name']):0;for($e=0;$e<$q;$e++){if(($A['error'][$e]??1)!==UPLOAD_ERR_OK||(int)$A['size'][$e]>10*1024*1024){continue;}$o=$A['tmp_name'][$e];$b=(string)(mime_content_type($o)?:'');if(!isset(Media::ALLOWED[$b])){continue;}$c=Media::ALLOWED[$b];if($c==='svg'){$s=(string)file_get_contents($o);if(preg_match('/<script|on[a-z]+\s*=|javascript:/i',$s)){continue;}}$p=$n=null;if(str_starts_with($b,'image/')&&$c!=='svg'){$k=@getimagesize($o);if(!$k){continue;}[$p,$n]=$k;}$u=gmdate('Y/m');$i=TP_ROOT.'/storage/media/'.$u;if(!is_dir($i)){mkdir($i,0775,true);}$w=slugify(pathinfo((string)$A['name'][$e],PATHINFO_FILENAME))?:'file';$W=$w.'-'.bin2hex(random_bytes(4)).'.'.$c;if(!move_uploaded_file($o,$i.'/'.$W)&&!rename($o,$i.'/'.$W)){continue;}Media::create(['filename'=>(string)$A['name'][$e],'path'=>$u.'/'.$W,'mime'=>$b,'size'=>(int)$A['size'][$e],'width'=>$p,'height'=>$n,'alt'=>[],'uploaded_by'=>Auth::id(),'created_at'=>now()]);$a++;}AuditLog::log('admin.media_upload',(string)$a);$this->flash($a?'success':'error',$a?t('admin.media_uploaded',['n'=>$a]):t('admin.media_rejected'));return $this->redirect('/admin/media');}public function delete(Request $Y,string $e):Response{$O=Media::find((int)$e);if($O){@unlink(TP_ROOT.'/storage/media/'.$O['path']);Media::delete((int)$e);AuditLog::log('admin.media_delete',$O['path']);}$this->flash('success',t('common.deleted'));return $this->redirect('/admin/media');}}